using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API for the given resource path.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The API resource path to fetch (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum length hint (e.g. \"2 sentences\").")] string? maxLength = null)
    {
        var instruction = maxLength is not null
            ? $"Summarize the following text in {maxLength}:"
            : "Summarize the following text concisely:";

        return
        [
            new(Role.User, $"{instruction}\n\n{text}"),
        ];
    }
}

